import { test, expect } from '@playwright/test';

test.describe('Delete Single Notification', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/notifications');
  });

  test('should successfully delete a single notification from the list', async ({ page }) => {
    // Verify notification list is visible
    const notificationList = page.getByRole('region', { name: /notification list/i });
    await expect(notificationList).toBeVisible();

    // Verify at least one notification exists
    const notificationItems = page.getByRole('listitem');
    await expect(notificationItems).toHaveCount(1);

    // Verify notification content
    const notificationContent = page.getByText(/new message/i);
    await expect(notificationContent).toBeVisible();

    // Verify delete button is visible and enabled
    const deleteButton = page.getByRole('button', { name: /delete/i });
    await expect(deleteButton).toBeVisible();
    await expect(deleteButton).not.toBeDisabled();

    // Click delete button
    await deleteButton.click();

    // Verify success message appears
    const successMessage = page.getByText(/notification deleted successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify notification is removed from the list
    await expect(notificationItems).toHaveCount(0);

    // Verify empty state message is displayed
    const emptyState = page.getByText(/no notifications/i);
    await expect(emptyState).toBeVisible();
  });

  test('should handle delete operation when notification is not found', async ({ page }) => {
    // Navigate to notifications page
    await page.goto('/notifications');

    // Verify notification list is visible
    const notificationList = page.getByRole('region', { name: /notification list/i });
    await expect(notificationList).toBeVisible();

    // Verify no notifications exist
    const notificationItems = page.getByRole('listitem');
    await expect(notificationItems).toHaveCount(0);

    // Verify empty state message is displayed
    const emptyState = page.getByText(/no notifications/i);
    await expect(emptyState).toBeVisible();

    // Attempt to click delete button (should not exist)
    const deleteButton = page.getByRole('button', { name: /delete/i });
    await expect(deleteButton).not.toBeVisible();

    // Verify error message is not displayed
    const errorMessage = page.getByText(/notification not found/i);
    await expect(errorMessage).not.toBeVisible();
  });
});
